CREATE TABLE game ( id INTEGER NOT NULL, nama VARCHAR(255) NOT NULL, tipe VARCHAR(50), kategori VARCHAR(500), exe_path VARCHAR(500), argumen VARCHAR(500), icon VARCHAR(255), aktif BOOLEAN, created_at DATETIME, updated_at DATETIME, operator_id VARCHAR(50), PRIMARY KEY (id) );
CREATE TABLE game_kategori ( id INTEGER NOT NULL, nama VARCHAR(100) NOT NULL, created_at DATETIME, updated_at DATETIME, PRIMARY KEY (id), UNIQUE (nama) );
CREATE TABLE grup ( id INTEGER NOT NULL, nama VARCHAR(50) NOT NULL, warna VARCHAR(20), keterangan VARCHAR(255), aktif BOOLEAN DEFAULT 1 NOT NULL, dibuat_pada DATETIME, PRIMARY KEY (id), UNIQUE (nama) );
CREATE TABLE hardware_monitor ( id INTEGER NOT NULL, pc_id INTEGER NOT NULL, cpu_usage FLOAT, cpu_temp FLOAT, gpu_temp FLOAT, total_ram VARCHAR(20), nic_speed VARCHAR(20), motherboard VARCHAR(100), cpu_name VARCHAR(100), gpu_name VARCHAR(100), active_window VARCHAR(255), hardware_baseline TEXT, hardware_current_specs TEXT, hardware_mismatch BOOLEAN, hardware_mismatch_desc TEXT, hardware_mismatch_time DATETIME, hardware_cctv_window TEXT, hardware_last_sync DATETIME, last_update DATETIME, PRIMARY KEY (id), UNIQUE (pc_id), FOREIGN KEY(pc_id) REFERENCES pc (id) );
CREATE TABLE maintenance_ticket ( id INTEGER NOT NULL, pc_id INTEGER NOT NULL, reporter VARCHAR(50) NOT NULL, kategori VARCHAR(30) NOT NULL, prioritas VARCHAR(10), judul VARCHAR(150) NOT NULL, deskripsi TEXT, status VARCHAR(20), resolusi TEXT, biaya INTEGER, created_at DATETIME, updated_at DATETIME, resolved_at DATETIME, resolved_by VARCHAR(50), PRIMARY KEY (id), FOREIGN KEY(pc_id) REFERENCES pc (id) );
CREATE TABLE member ( id INTEGER NOT NULL, username VARCHAR(50) NOT NULL, password_hash VARCHAR(256) NOT NULL, nama_lengkap VARCHAR(100), email VARCHAR(120), no_hp VARCHAR(20), grup_id INTEGER NOT NULL, aktif BOOLEAN, dibuat_pada DATETIME, waktu_tersimpan INTEGER, kadaluarsa_pada DATETIME, PRIMARY KEY (id), UNIQUE (username), FOREIGN KEY(grup_id) REFERENCES grup (id) );
CREATE TABLE menu_item ( id INTEGER NOT NULL, nama VARCHAR(100) NOT NULL, harga INTEGER NOT NULL, stok INTEGER NOT NULL, gambar_path VARCHAR(255), is_active BOOLEAN DEFAULT 1 NOT NULL, PRIMARY KEY (id), UNIQUE (nama) );
CREATE TABLE menu_stock_log ( id INTEGER NOT NULL, menu_id INTEGER, menu_nama VARCHAR(100) NOT NULL, tipe VARCHAR(20) NOT NULL, jumlah_masuk INTEGER NOT NULL, stok_sebelum INTEGER NOT NULL, stok_sesudah INTEGER NOT NULL, operator VARCHAR(100) NOT NULL, catatan VARCHAR(255), created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(menu_id) REFERENCES menu_item (id) ON DELETE SET NULL );
CREATE TABLE mikrotik_config ( id INTEGER NOT NULL, enabled BOOLEAN NOT NULL, host VARCHAR(100), port INTEGER NOT NULL, username VARCHAR(100), password VARCHAR(255), hotspot_profile VARCHAR(100) NOT NULL, updated_at DATETIME, PRIMARY KEY (id) );
CREATE TABLE paket ( id INTEGER NOT NULL, nama VARCHAR(100) NOT NULL, durasi_menit INTEGER NOT NULL, harga INTEGER NOT NULL, kadaluarsa_hari INTEGER, grup_id INTEGER NOT NULL, aktif BOOLEAN, dibuat_pada DATETIME, PRIMARY KEY (id), UNIQUE (nama), FOREIGN KEY(grup_id) REFERENCES grup (id) );
CREATE TABLE pc ( id INTEGER NOT NULL, kode VARCHAR(20) NOT NULL, nama VARCHAR(50), ip_address VARCHAR(15), mac_address VARCHAR(17), grup_id INTEGER NOT NULL, zona VARCHAR(50), last_activity DATETIME, aktif BOOLEAN, is_admin_mode BOOLEAN, pos_x INTEGER, pos_y INTEGER, PRIMARY KEY (id), UNIQUE (kode), FOREIGN KEY(grup_id) REFERENCES grup (id) );
CREATE TABLE pc_process ( id INTEGER NOT NULL, pc_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, title VARCHAR(255), last_update DATETIME, PRIMARY KEY (id), FOREIGN KEY(pc_id) REFERENCES pc (id) );
CREATE TABLE pc_uptime_log ( id INTEGER NOT NULL, pc_id INTEGER NOT NULL, tanggal DATE NOT NULL, total_online_seconds INTEGER NOT NULL, total_billing_seconds INTEGER NOT NULL, first_seen DATETIME, last_seen DATETIME, PRIMARY KEY (id), CONSTRAINT uq_pc_uptime_pc_tanggal UNIQUE (pc_id, tanggal), FOREIGN KEY(pc_id) REFERENCES pc (id) );
CREATE TABLE sesi ( id INTEGER NOT NULL, tipe VARCHAR(10) NOT NULL, member_id INTEGER, user_id INTEGER, pc_id INTEGER, paket_id INTEGER, sesi_asal_id INTEGER, nama_guest VARCHAR(100), token_sesi VARCHAR(64), mulai_pada DATETIME, selesai_pada DATETIME, durasi_beli_menit INTEGER, total_bayar INTEGER, status VARCHAR(10), is_admin BOOLEAN, waktu_mulai_sesi DATETIME, waktu_tersimpan_awal INTEGER, last_sync DATETIME, menit_pause_total INTEGER, sisa_menit_saat_mati INTEGER, is_blackout_suspect BOOLEAN, is_blackout_resolved BOOLEAN, waktu_resolved DATETIME, is_afk BOOLEAN NOT NULL, afk_pin VARCHAR(100), afk_sejak DATETIME, PRIMARY KEY (id), FOREIGN KEY(member_id) REFERENCES member (id), FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE SET NULL, FOREIGN KEY(pc_id) REFERENCES pc (id) ON DELETE SET NULL, FOREIGN KEY(paket_id) REFERENCES paket (id), FOREIGN KEY(sesi_asal_id) REFERENCES sesi (id) ON DELETE SET NULL, UNIQUE (token_sesi) );
CREATE TABLE settings ( id INTEGER NOT NULL, "key" VARCHAR(100) NOT NULL, value TEXT NOT NULL, updated_at DATETIME, PRIMARY KEY (id), UNIQUE ("key") );
CREATE TABLE shift_record ( id INTEGER NOT NULL, kasir_id INTEGER NOT NULL, waktu_mulai DATETIME NOT NULL, waktu_selesai DATETIME, modal_awal INTEGER NOT NULL, total_billing INTEGER, total_kantin INTEGER, total_qris INTEGER, total_refund INTEGER, uang_fisik INTEGER, selisih INTEGER, catatan VARCHAR(255), detail_metode_json TEXT, status VARCHAR(10) NOT NULL, PRIMARY KEY (id), FOREIGN KEY(kasir_id) REFERENCES user (id) );
CREATE TABLE system_tutorials ( id INTEGER NOT NULL, title VARCHAR(255) NOT NULL, icon VARCHAR(50), category VARCHAR(50), content TEXT NOT NULL, urutan INTEGER, created_at DATETIME, updated_at DATETIME, PRIMARY KEY (id) );
CREATE TABLE transaksi ( id INTEGER NOT NULL, sesi_id INTEGER, member_id INTEGER, paket_id INTEGER, user_id INTEGER, jenis VARCHAR(30) NOT NULL, jumlah INTEGER, menit INTEGER, keterangan VARCHAR(200), dibuat_pada DATETIME, no_nota VARCHAR(50), is_refunded BOOLEAN, metode_pembayaran VARCHAR(50), operator VARCHAR(100), PRIMARY KEY (id), FOREIGN KEY(sesi_id) REFERENCES sesi (id), FOREIGN KEY(member_id) REFERENCES member (id) ON DELETE SET NULL, FOREIGN KEY(paket_id) REFERENCES paket (id), FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE SET NULL );
CREATE TABLE transaksi_menu ( id INTEGER NOT NULL, no_nota VARCHAR(50) NOT NULL, menu_id INTEGER NOT NULL, jumlah INTEGER NOT NULL, total_harga INTEGER NOT NULL, pc_kode VARCHAR(20), tanggal DATETIME, kasir_id INTEGER, tunai INTEGER, kembalian INTEGER, metode_pembayaran VARCHAR(50), operator VARCHAR(100), PRIMARY KEY (id), FOREIGN KEY(menu_id) REFERENCES menu_item (id), FOREIGN KEY(kasir_id) REFERENCES user (id) ON DELETE SET NULL );
CREATE TABLE turnamen ( id INTEGER NOT NULL, nama VARCHAR(100) NOT NULL, deskripsi VARCHAR(255), status VARCHAR(20), dibuat_pada DATETIME, PRIMARY KEY (id), UNIQUE (nama) );
CREATE TABLE turnamen_match ( id INTEGER NOT NULL, turnamen_id INTEGER NOT NULL, tahap_id INTEGER NOT NULL, round_number INTEGER NOT NULL, match_number INTEGER NOT NULL, tim1_id INTEGER, tim2_id INTEGER, skor1 INTEGER, skor2 INTEGER, pemenang_id INTEGER, bo_format INTEGER, next_match_id INTEGER, dibuat_pada DATETIME, PRIMARY KEY (id), FOREIGN KEY(turnamen_id) REFERENCES turnamen (id), FOREIGN KEY(tahap_id) REFERENCES turnamen_tahap (id), FOREIGN KEY(tim1_id) REFERENCES turnamen_tim (id) ON DELETE SET NULL, FOREIGN KEY(tim2_id) REFERENCES turnamen_tim (id) ON DELETE SET NULL, FOREIGN KEY(pemenang_id) REFERENCES turnamen_tim (id) ON DELETE SET NULL, FOREIGN KEY(next_match_id) REFERENCES turnamen_match (id) ON DELETE SET NULL );
CREATE TABLE turnamen_tahap ( id INTEGER NOT NULL, turnamen_id INTEGER NOT NULL, nama VARCHAR(50) NOT NULL, tipe_format VARCHAR(20) NOT NULL, urutan INTEGER NOT NULL, status VARCHAR(20), dibuat_pada DATETIME, PRIMARY KEY (id), FOREIGN KEY(turnamen_id) REFERENCES turnamen (id) );
CREATE TABLE turnamen_tim ( id INTEGER NOT NULL, turnamen_id INTEGER NOT NULL, nama_tim VARCHAR(100) NOT NULL, status_aktif BOOLEAN, dibuat_pada DATETIME, PRIMARY KEY (id), FOREIGN KEY(turnamen_id) REFERENCES turnamen (id) );
CREATE TABLE user ( id INTEGER NOT NULL, username VARCHAR(50) NOT NULL, password_hash VARCHAR(256) NOT NULL, nama_lengkap VARCHAR(100), role VARCHAR(20), aktif BOOLEAN, dibuat_pada DATETIME, kuota_main_bulanan INTEGER, sisa_kuota_menit INTEGER, terakhir_reset_kuota VARCHAR(7), PRIMARY KEY (id), UNIQUE (username) );
CREATE INDEX ix_menu_stock_log_created_at ON menu_stock_log (created_at);
CREATE INDEX ix_menu_stock_log_menu_id ON menu_stock_log (menu_id);
CREATE INDEX ix_pc_process_pc_id ON pc_process (pc_id);
CREATE INDEX ix_pc_uptime_log_tanggal ON pc_uptime_log (tanggal);
CREATE INDEX ix_sesi_pc_id ON sesi (pc_id);
CREATE INDEX ix_sesi_status ON sesi (status);
CREATE INDEX ix_transaksi_dibuat_pada ON transaksi (dibuat_pada);
CREATE INDEX ix_transaksi_menu_tanggal ON transaksi_menu (tanggal);
CREATE UNIQUE INDEX ix_transaksi_no_nota ON transaksi (no_nota);
CREATE INDEX ix_transaksi_sesi_id ON transaksi (sesi_id);
CREATE UNIQUE INDEX uq_aktif_sesi_member ON sesi (member_id) WHERE status = 'aktif' AND member_id IS NOT NULL;
CREATE UNIQUE INDEX uq_aktif_sesi_pc ON sesi (pc_id) WHERE status = 'aktif' AND pc_id IS NOT NULL;
CREATE UNIQUE INDEX uq_aktif_shift ON shift_record (status) WHERE status = 'AKTIF';
